import random
from collections import deque

def compute_distances(adj, n):
    dist = [[float('inf')]*n for _ in range(n)]
    neighbors = [[] for _ in range(n)]
    for a,b in adj:
        neighbors[a].append(b)
        neighbors[b].append(a)
    for u in range(n):
        dist[u][u] = 0
        q = deque([u])
        while q:
            x = q.popleft()
            for y in neighbors[x]:
                if dist[u][y] == float('inf'):
                    dist[u][y] = dist[u][x] + 1
                    q.append(y)
    return dist

def can_add_edge(adj, n, u, v):
    dist = compute_distances(adj, n)
    d = dist[u][v]
    if d == float('inf'):
        return True
    return d >= 7

