import random
from collections import deque

def has_short_path(adj, n, u, v, max_len):
    # BFS from u up to depth max_len
    if u == v:
        return True
    visited = {u}
    q = deque([(u, 0)])
    neighbors = [[] for _ in range(n)]
    for a,b in adj:
        neighbors[a].append(b)
        neighbors[b].append(a)
    while q:
        x, d = q.popleft()
        if d >= max_len:
            continue
        for y in neighbors[x]:
            if y == v:
                return True
            if y not in visited:
                visited.add(y)
                q.append((y, d+1))
    return False

