def girth(edges, n):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for u in range(n):
        for v in adj[u]:
            if v &lt; u:
                continue
            # Remove edge (u,v)
            temp_adj = [list(a) for a in adj]
            temp_adj[u].remove(v)
            temp_adj[v].remove(u)

            q = deque([u])
            dist = {u: 0}
            found = False
            while q and not found:
                x = q.popleft()
