                    if y == v:
                        min_cycle = min(min_cycle, dist[x] + 2)
                        found = True
                        break
                    if y not in dist:
                        dist[y] = dist[x] + 1
                        q.append(y)
                if found:
                    break

    return min_cycle if min_cycle != float('inf') else float('inf')

